\end{align*}	

\begin{align*}
\alpha_\mathrm{r} &=\left. \frac{1}{R_\mathrm{r0}} \cdot \frac{\mathrm{d}R_\mathrm{r}}{\mathrm{d}T}\right|_{T_0} 

\alpha_\mathrm{r} &=\frac{1}{R_{10}+R_{20}}\left(\underbrace{ \left. \frac{\mathrm{d}R_\mathrm{1}}{\mathrm{d}T}\right| _{T_0}}_{\alpha_1 R_{10}} + \underbrace{ \left. \frac{\mathrm{d}R_\mathrm{2}}{\mathrm{d}T}\right| _{T_0}}_{\alpha_2 R_{20}}\right) 

\alpha_\mathrm{r} &=\frac{\alpha_1 R_{10}+ \alpha_2 R_{20}}{R_{10}+R_{20}}
\end{align*}	

- \begin{align*}
R_\mathrm{p}(T) &= \dfrac{1}{\dfrac{1}{R_1(T)} + \dfrac{1}{R_2(T)}} 

R_\mathrm{p0} &= R_\mathrm{p}(T_0)=\dfrac{1}{\dfrac{1}{R_{10}} + \dfrac{1}{R_{20}}}=\dfrac{R_{10}R_{20}}{R_{10}+R_{20}}
\end{align*}

\begin{align*}
\alpha_\mathrm{p} &=\left. \frac{1}{R_\mathrm{p0}} \cdot \frac{\mathrm{d}R_\mathrm{p}}{\mathrm{d}T}\right|_{T_0} 

&= \frac{1}{R_\mathrm{p0}}\cdot \frac{-1}{\left(\dfrac{1}{R_{1}}+\dfrac{1}{R_{2}}\right)^2}\left(\underbrace{\frac{-1}{R_1^2} \left. \frac{\mathrm{d}R_\mathrm{1}}{\mathrm{d}T}\right| _{T_0}}_{- \dfrac{1}{R_{10}}\alpha_1} + \underbrace{ \frac{-1}{R_2^2} \left. \frac{\mathrm{d}R_\mathrm{2}}{\mathrm{d}T}\right| _{T_0}}_{- \dfrac{1}{R_{20}}\alpha_2}\right) 

&= \frac{1}{R_\mathrm{p0}}\cdot R_\mathrm{p0}^2 \cdot\left(\alpha_1 \dfrac{1}{R_{10}}+ \alpha_2 \dfrac{1}{R_{20}}\right) 

\alpha_\mathrm{p} &=\frac{\alpha_1 \dfrac{1}{R_{10}}+ \alpha_2 \dfrac{1}{R_{20}}}{\dfrac{1}{R_{10}}+\dfrac{1}{R_{20}}} = \frac{\alpha_2 R_{10}+ \alpha_1 R_{20}}{R_{10}+R_{20}}
